{"path": "/tmp/sv-1eaa717be8094361935c9b7edfb435f0/Components/Pages/Board/TaskSearchBar.razor", "file_text": "@* Search bar for filtering tasks by title *@

<div class="search-bar">
    <input type="text" placeholder="Search tasks by title..."
           value="@SearchText"
           @oninput="OnInput" />
</div>

@code {
    [Parameter] public string SearchText { get; set; } = "";
    [Parameter] public EventCallback<string> SearchTextChanged { get; set; }

    private async Task OnInput(ChangeEventArgs e)
    {
        var value = e.Value?.ToString() ?? "";
        await SearchTextChanged.InvokeAsync(value);
    }
}
"}

